        function abrir_pdf($value,$pdf){//function abrir_pdf
            
                $pageCount = $pdf->setSourceFile($value);
                for ($pageNo = 1; $pageNo <= $pageCount; $pageNo++) {

                    $templateId = $pdf->importPage($pageNo);
                    $size = $pdf->getTemplateSize($templateId);

                    $pdf->AddPage('L', array($size['width'], $size['height']));//$size['height']+4.2
                 
                    $pdf->useTemplate($templateId);
                    $pdf->SetAutoPageBreak(false);

                    $rest = substr($value, 21);

                    $pdf->Output('F','FUPs/Masivo_ORIGINAL/bajas/'.$rest);
                }
        }//function abrir_pdf

        function buscar($buscar){

            $pdf = new \setasign\Fpdi\Fpdi('L','mm','LEGAL');

            $directorio = "FUPs/Masivo_Original/";
            $directorio_total = glob($directorio."*.pdf");
            
            $qna = "Fecha";
            $qna1 = "Qna";

            $matches_qna = "";
            $matches_qna1 = "";
            $malo = "";
            $matches = array_filter($directorio_total, function($var) use ($buscar) { return preg_match("/$buscar/i", $var); });    if($matches){//matches
                $contar = 1;
                foreach ($matches as $value){//foreach
                    
                    if($contar==1){

                        $findme   = '__';
                        $pos1 = strpos($value, $findme);
                        if ($pos1 == true) {
                            //rehacer_fup($buscar,$value);
                            $malo = $buscar;
                            abrir_pdf("malo",$pdf);                    //unlink($value);
                        }else{
                            $findme   = '_';
                            $pos = strpos($value, $findme);
                            if ($pos == true) {
                                $matches_qna = strrpos($value, $qna);
                                $matches_qna1 = strrpos($value, $qna1);

                                if ($matches_qna  == true && $matches_qna1 != true){ //cuando es por fecha
                                    if($fec_imp != ""){
                                        abrir_pdf($value,$pdf);
                                    }
                                }
                                else if ($matches_qna  != true && $matches_qna1 == true){//cuando es por qna
                                    if($fec_imp != ""){
                                        abrir_pdf($value,$pdf);
                                    }
                                }else{
                                    abrir_pdf($value,$pdf);
                                }
                            }  
                        } 
                    }elseif($contar>1){
                        $findme   = '__';
                        $pos1 = strpos($value, $findme);
                        if ($pos1 == true) {
                            //rehacer_fup($buscar,$value);  
                        } 
                    }
                    $contar++;
                }//foreach  
            }//matches
        }//buscar

